package com.tekwatt.user.controller;import com.tekwatt.user.dto.*;import com.tekwatt.user.entity.*;import com.tekwatt.user.service.UserDirectoryService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/users/directory")public class UserDirectoryController{private final UserDirectoryService service;public UserDirectoryController(UserDirectoryService s){service=s;}@GetMapping("/partners")List<Partner>partners(@RequestParam UUID tenantId){return service.partners(tenantId);}@PostMapping("/partners")@ResponseStatus(HttpStatus.CREATED)Partner partner(@Valid@RequestBody PartnerRequest r){return service.savePartner(null,r);}@PutMapping("/partners/{id}")Partner partner(@PathVariable UUID id,@Valid@RequestBody PartnerRequest r){return service.savePartner(id,r);}@DeleteMapping("/partners/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void deletePartner(@PathVariable UUID id){service.deletePartner(id);}@GetMapping("/technicians")List<Technician>technicians(@RequestParam UUID tenantId){return service.technicians(tenantId);}@PostMapping("/technicians")@ResponseStatus(HttpStatus.CREATED)Technician technician(@Valid@RequestBody TechnicianRequest r){return service.saveTechnician(null,r);}@PutMapping("/technicians/{id}")Technician technician(@PathVariable UUID id,@Valid@RequestBody TechnicianRequest r){return service.saveTechnician(id,r);}@DeleteMapping("/technicians/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void deleteTechnician(@PathVariable UUID id){service.deleteTechnician(id);}@GetMapping("/rfid-cards")List<RfidCard>cards(@RequestParam UUID tenantId){return service.cards(tenantId);}@PostMapping("/rfid-cards")@ResponseStatus(HttpStatus.CREATED)RfidCard issue(@Valid@RequestBody RfidCardRequest r){return service.issue(r);}@PatchMapping("/rfid-cards/{id}/status")RfidCard status(@PathVariable UUID id,@RequestBody Map<String,String>b){return service.cardStatus(id,b.get("status"));}}
